import{St as e,at as t,it as n,o as r,ot as i,st as a,tt as o,vt as s}from"./chunks/framework.DQt_9H6f.js";var c=JSON.parse(`{"title":"Quick start guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md"}`),l={name:`guide/quick-start.md`};function u(r,c,l,u,d,f){let p=e(`QuickStartHero`),m=e(`wa-icon`),h=e(`GuideIntroHero`);return s(),n(`div`,null,[c[6]||=o(`h1`,{id:`quick-start-guide`,tabindex:`-1`},[i(`Quick start guide `),o(`a`,{class:`header-anchor`,href:`#quick-start-guide`,"aria-label":`Permalink to “Quick start guide”`},`​`)],-1),c[7]||=o(`p`,null,[i(`On a fresh install, the `),o(`strong`,null,`setup assistant`),i(` walks you through connecting a model, checking your environment, and running a first task. This page is the reference for the `),o(`strong`,null,`New task`),i(` view in VS Code and its CLI equivalents.`)],-1),a(p),c[8]||=t(`<p class="hero-caption">The New task view: pick a model, write one sentence that names your file, and select Start task.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>Editing a document typically takes five steps:</p><ol><li>Pick a model</li><li>Write a short instruction that names your file</li><li>Select <strong>Start task</strong></li><li>Approve the program run the assistant proposes</li><li>Review the diff</li></ol><div class="tip custom-block"><p class="custom-block-title">Get started walkthrough</p><p>Inside VS Code you can open the <strong>Get started with TeXRA</strong> walkthrough from the Get Started page (or by running <code>TeXRA: Open Getting Started Walkthrough</code>). It tells the same story in four steps (connect a model, open your paper, run the setup assistant, your first task) and links directly to the relevant commands.</p></div><div class="tip custom-block"><p class="custom-block-title">Prefer the terminal?</p><p>This guide walks through the VS Code extension. If you installed the <a href="./texra-cli.html">CLI</a>, the same assistant runs from the command line: start an interactive session with <code>texra chat</code>, or run a single program with <code>texra run annotate --input draft.tex</code>.</p></div><h2 id="add-a-key-or-connect-a-subscription" tabindex="-1">Add a key or connect a subscription <a class="header-anchor" href="#add-a-key-or-connect-a-subscription" aria-label="Permalink to “Add a key or connect a subscription”">​</a></h2><p>On a fresh install, the <strong>Connect a model</strong> card in the TeXRA panel offers two quick choices (other subscriptions connect from Settings):</p><ol><li><strong>Use your own API keys</strong>: Open <strong>Settings → Models → API keys</strong> (gear icon at the top of the panel) and paste a provider key, or add keys to a project <code>.env</code> file.</li><li><strong>Use ChatGPT subscription</strong>: Sign in under <strong>Settings → Models → Subscriptions</strong>.</li><li><strong>Other provider subscriptions</strong>: Connect Grok (xAI), Kimi Code, or the GLM Coding Plan from the same <strong>Models</strong> page.</li></ol><p>See <a href="./models.html#setting-api-keys">Models → Setting API keys</a> for the full provider list. There is no TeXRA account — everything runs directly on your configured credentials.</p><p>Once connected, the <strong>setup assistant</strong> checks your environment and runs a quick test edit ending at a diff. <a href="./first-run.html">First run</a> covers the same steps manually.</p><div class="tip custom-block"><p class="custom-block-title">CLI credentials</p><p>The terminal uses the same paths: provider env vars for your own keys, <code>texra auth chatgpt login</code> for a ChatGPT subscription, <code>texra auth grok login</code> for a Grok (xAI) subscription, or <code>/login</code> in a chat to manage the ChatGPT and Grok sign-ins. Running <code>texra</code> without any of these opens the chat with a <strong>Connect a model</strong> panel instead of an error. <code>texra setup</code> is the terminal counterpart of the setup assistant: it walks you through a ChatGPT sign-in or an API key, then your environment and first task. Read the <a href="./texra-cli.html#authentication">Authentication section</a> of the CLI guide.</p></div><h2 id="the-new-task-view-in-detail" tabindex="-1">The New task view in detail <a class="header-anchor" href="#the-new-task-view-in-detail" aria-label="Permalink to “The New task view in detail”">​</a></h2><p>Open the TeXRA panel from the TeXRA icon in the Secondary Side Bar, or run <strong>TeXRA: New Task</strong> (<code>Ctrl+Alt+M</code>, <code>Cmd+Option+M</code> on macOS).</p><h3 id="choose-a-model-and-write-the-instruction" tabindex="-1">Choose a model and write the instruction <a class="header-anchor" href="#choose-a-model-and-write-the-instruction" aria-label="Permalink to “Choose a model and write the instruction”">​</a></h3><p>The menu at the bottom of the instruction box picks the model (e.g. <strong>Sonnet 5.5</strong>, whose id is <code>anthropic/claude-sonnet-5-5</code>). There is no agent to pick: one assistant takes every task, and splits a larger job across helper agents and <a href="./programs.html">programs</a> itself.</p><p>Then say what you want, and on which file, in the text area:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Polish main.tex: improve the clarity and flow, and make the technical</span></span>
<span class="line"><span>explanations more accessible. Fix grammatical issues and awkward phrasing.</span></span>
<span class="line"><span>Keep the terminology consistent and do not change the equations.</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Effective Instructions</p><p>Be specific about your objectives: state both what the assistant should improve and what constraints (notation, theorem numbering, environment structures) it must preserve.</p></div><p>To send figures or other media along, use <strong>Attach</strong> in the instruction box.</p><h3 id="approve-what-it-proposes" tabindex="-1">Approve what it proposes <a class="header-anchor" href="#approve-what-it-proposes" aria-label="Permalink to “Approve what it proposes”">​</a></h3><p>The assistant edits your files itself and asks before each change under your approval policy. For a job one of the <a href="./programs.html">programs</a> packages (<code>annotate</code> for a referee&#39;s comments, <code>prove</code> for Lean proofs) it proposes a program run: the proposal card shows the program, the instruction and the files. Approve it, or select <strong>Edit</strong> to change the files first.</p><h3 id="start-the-task-and-watch-it" tabindex="-1">Start the task and watch it <a class="header-anchor" href="#start-the-task-and-watch-it" aria-label="Permalink to “Start the task and watch it”">​</a></h3>`,23),o(`p`,null,[c[0]||=i(`Select `,-1),c[1]||=o(`strong`,null,`Start task`,-1),c[2]||=i(` (`,-1),a(m,{library:`texra`,name:`arrow-up`}),c[3]||=i(`). The Tasks view opens in the TeXRA panel and streams progress live. Read the `,-1),c[4]||=o(`a`,{href:`./progress-board.html`},`Tasks view guide`,-1),c[5]||=i(` for details.`,-1)]),a(h),c[9]||=t(`<p class="hero-caption">The Tasks view streams progress live (helper agents and tool calls).</p><h3 id="review-results" tabindex="-1">Review results <a class="header-anchor" href="#review-results" aria-label="Permalink to “Review results”">​</a></h3><p>The files in your project are the result. Open them in the editor, or run <code>git diff</code>, to see what changed; ask the assistant for a <code>latexdiff</code> PDF when you want the changes marked up in the compiled document.</p><h2 id="from-the-cli" tabindex="-1">From the CLI <a class="header-anchor" href="#from-the-cli" aria-label="Permalink to “From the CLI”">​</a></h2><p>The same assistant and programs run from the terminal. After <code>npm install -g @texra-ai/cli</code> (Node.js 22.22.2 or later in 22.x, or Node.js 24.15 or later) or <code>brew install texra-ai/tap/texra</code>:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Set ANTHROPIC_API_KEY / OPENAI_API_KEY in your shell, or connect a subscription:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">texra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chatgpt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Or let the guided setup handle credentials, environment, and your first task:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">texra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># One-shot run: the assistant edits draft.tex in place and prints its answer.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">texra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --instruction</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Improve the clarity of draft.tex; preserve math and citations.&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --print</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Or open an interactive chat:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">texra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Included API credits on paid plans</p><p>Claude Max/Team and ChatGPT Pro/Business subscriptions include monthly API credits that an ordinary provider API key can spend; see <a href="./installation.html#setting-up-api-keys">Getting API keys</a>.</p></div><p>Task history is shared across the CLI, VS Code extension, and desktop app, so a task started in the CLI shows up in the Tasks view (and vice versa). Read the <a href="./texra-cli.html">TeXRA CLI guide</a> for sign-in, project defaults, and headless output formats.</p><h2 id="common-quick-tasks" tabindex="-1">Common quick tasks <a class="header-anchor" href="#common-quick-tasks" aria-label="Permalink to “Common quick tasks”">​</a></h2><p>Some common tasks to try with TeXRA. Ask the assistant in the New task view, or run the program from the terminal:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Task</th><th style="text-align:left;">Ask the assistant</th><th style="text-align:left;">From the terminal</th></tr></thead><tbody><tr><td style="text-align:left;">Proofread a draft</td><td style="text-align:left;">&quot;Proofread draft.tex: fix typos, grammar and LaTeX formatting only.&quot;</td><td style="text-align:left;"><code>texra run chat --instruction &quot;Proofread draft.tex: typos, grammar and LaTeX formatting only.&quot;</code></td></tr><tr><td style="text-align:left;">Polish writing style</td><td style="text-align:left;">&quot;Polish draft.tex for clarity and flow; keep the math and citations.&quot;</td><td style="text-align:left;"><code>texra run chat --instruction &quot;Polish draft.tex for clarity and flow.&quot;</code></td></tr><tr><td style="text-align:left;">Review as a first reader</td><td style="text-align:left;">&quot;Annotate draft.tex as a first-time reader would.&quot;</td><td style="text-align:left;"><code>texra run annotate --input draft.tex --instruction &quot;Read as a first-time reader&quot;</code></td></tr><tr><td style="text-align:left;">Build slides</td><td style="text-align:left;">&quot;Turn paper.tex into a Beamer slide deck, slides.tex.&quot;</td><td style="text-align:left;"><code>texra run chat --instruction &quot;Turn paper.tex into a Beamer slide deck, slides.tex.&quot;</code></td></tr></tbody></table><h2 id="understanding-the-output" tabindex="-1">Understanding the output <a class="header-anchor" href="#understanding-the-output" aria-label="Permalink to “Understanding the output”">​</a></h2><p>A task changes the files in your project, so your editor and <code>git diff</code> show its result. Each task also has a run folder under <code>executions/&lt;run-id&gt;/</code> in the project&#39;s storage folder under <code>~/.texra</code>, shared by the CLI, VS Code and the desktop app, which holds its conversation and logs. Read <a href="./first-run.html">First run</a> for the terminal walkthrough.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next steps”">​</a></h2><p>After your first task with TeXRA, you can:</p><ul><li>Explore the <a href="./programs.html">programs</a> for specialized tasks</li><li>Learn about <a href="./latex-diff.html">LaTeX diff</a> for comparing document versions</li><li>Tune your workflow with <a href="./configuration.html">custom configuration</a></li></ul><p>For issues or questions, read the <a href="/guide/troubleshooting.html">troubleshooting guide</a> or check the <a href="https://github.com/LionSR/TeXRA/issues" target="_blank" rel="noreferrer">GitHub issues page</a>.</p>`,17)])}var d=r(l,[[`render`,u]]);export{c as __pageData,d as default};